import { describe, it, expect, beforeEach } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";
import { newDb } from "pg-mem";
import type { Queryable } from "./db.js";
import { seedDatabase } from "./seed.js";
import { campaignsAsMap, listCampaigns } from "./repositories/campaigns.js";
import { listCreatives } from "./repositories/creatives.js";
import { ensureSession, getSession } from "./repositories/sessions.js";
import { upsertOpportunity } from "./repositories/opportunities.js";
import { saveDecision, getDecisionsBySession } from "./repositories/decisions.js";
import { appendEvent, getEventsBySession } from "./repositories/events.js";
import { decide, type AdOpportunity, type SessionContext } from "@ssai/core";

const here = dirname(fileURLToPath(import.meta.url));
const MIG_DIR = resolve(here, "../../../migrations");
const SCHEMA = readdirSync(MIG_DIR)
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .map((f) => readFileSync(join(MIG_DIR, f), "utf8"))
  .join("\n");

function freshDb(): Queryable {
  const mem = newDb();
  mem.public.none(SCHEMA); // load full schema (multi-statement)
  const { Pool } = mem.adapters.createPg();
  return new Pool() as unknown as Queryable;
}

let db: Queryable;
beforeEach(() => {
  db = freshDb();
});

describe("seed + inventory repositories", () => {
  it("seeds 5 channels and assembles campaign target channels", async () => {
    await seedDatabase(db);
    const campaigns = await listCampaigns(db);
    const food = campaigns.find((c) => c.campaignId === "camp_food_a");
    expect(food?.targetChannels).toEqual(["channel_food"]);
    const appliance = campaigns.find((c) => c.campaignId === "camp_appliance_b");
    expect(appliance?.targetChannels).toContain("channel_food");
    expect(appliance?.targetChannels).toContain("channel_entertainment");
  });

  it("returns creatives with numeric duration/priority/weight", async () => {
    await seedDatabase(db);
    const creatives = await listCreatives(db);
